mapper.update:
update biz_progress_stage
stage_name = #{stageName}, plan_start_date = #{planStartDate}, plan_end_date = #{planEndDate}, actual_start_date = #{actualStartDate}, actual_end_date = #{actualEndDate}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where stage_id = #{stageId}

mapper.select:
select a.attachment_id, a.biz_type, a.biz_id, a.file_url, a.file_name, a.file_size, a.upload_user_id, a.create_by, a.create_time from biz_attachment a where a.biz_type = 'site_stage' and a.biz_id in
#{stageId}
order by a.attachment_id

mapper.delete:
delete from biz_attachment
where biz_type = 'site_stage'
and biz_id in (
    select stage_id from biz_progress_stage where site_id in

        #{siteId}

)
